namespace FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Interfaces.Rest.Resources;

/// <summary>
///     Resource representing a change to a synchronized alert. Kind is Evidence, Cleared or Acknowledged.
/// </summary>
/// <param name="OperationId">The identifier generated by the gateway for the change.</param>
/// <param name="AlertId">The alert the change applies to.</param>
/// <param name="Kind">The kind of change.</param>
/// <param name="DeviceId">The device that captured the evidence readings.</param>
/// <param name="ReadingIds">The evidence readings.</param>
/// <param name="OccurredAt">The instant the change happened.</param>
/// <param name="AuthorId">The account that registered the attention.</param>
/// <param name="Finding">What the author found.</param>
/// <param name="Action">What the author did.</param>
/// <param name="ExpectedVersion">The alert version last read by the author.</param>
public record EdgeAlertChangeResource(
    Guid OperationId,
    Guid AlertId,
    string? Kind,
    Guid? DeviceId,
    IReadOnlyList<Guid>? ReadingIds,
    DateTimeOffset? OccurredAt,
    Guid? AuthorId,
    string? Finding,
    string? Action,
    int? ExpectedVersion);
